import{_ as d,a8 as r,o as l,c as p,au as g,a as i,a3 as o,K as e,L as h}from"./chunks/framework.Bftk7dsM.js";import"./chunks/theme.C-z6hHSd.js";const N=JSON.parse('{"title":"七种笔记法其实是一套流水线的七个工位","description":"","frontmatter":{"title":"七种笔记法其实是一套流水线的七个工位","abstract":"闪念、文献、永久、原子、MOC、常青、卡片盒——这七个名字经常被并列成「选一个用」，但它们不是选项，是同一条产线的七个工位。真正的坑在于跳过工位，而不在于选错方法。","created":"2026-11-10T00:00:00.000Z","updated":"2026-11-10T00:00:00.000Z","type":"科普","tags":["知识管理","笔记方法","学习方法"],"category":["📚 个人知识管理","个人能力"]},"headers":[],"relativePath":"vault/Knowledge/Methods/七种笔记法其实是一套流水线的七个工位.md","filePath":"vault/Knowledge/Methods/七种笔记法其实是一套流水线的七个工位.md","lastUpdated":1794320166000}'),_={name:"vault/Knowledge/Methods/七种笔记法其实是一套流水线的七个工位.md"};function b(c,t,m,u,f,P){const a=r("VPNolebaseInlineLinkPreview"),n=r("NolebaseGitContributors"),s=r("NolebaseGitChangelog");return l(),p("div",null,[t[3]||(t[3]=g('<h1 id="七种笔记法其实是一套流水线的七个工位" tabindex="-1">七种笔记法其实是一套流水线的七个工位 <a class="header-anchor" href="#七种笔记法其实是一套流水线的七个工位" aria-label="Permalink to “七种笔记法其实是一套流水线的七个工位”">​</a></h1><p>关于笔记方法的文章大多是并列式的：闪念笔记法、文献笔记法、永久笔记法、原子笔记法、MOC、常青笔记、卡片盒笔记——七种，挑一个适合你的。</p><p>这个框架是错的。</p><p>它们不是七个可选项，是<strong>同一条流水线上的七个工位</strong>。你不需要选，你需要的是让原料依次经过它们。任何一环缺失，最后产出的就不是知识，只是一批写得很整齐的文档。</p><h2 id="一、七个工位分别在干什么" tabindex="-1">一、七个工位分别在干什么 <a class="header-anchor" href="#一、七个工位分别在干什么" aria-label="Permalink to “一、七个工位分别在干什么”">​</a></h2><p>先看清分工，再谈流程。</p><table tabindex="0"><thead><tr><th>工位</th><th>职责</th><th>一句话判断</th></tr></thead><tbody><tr><td>闪念笔记</td><td>接住念头，不做整理</td><td>十秒内能记完，否则不算闪念</td></tr><tr><td>文献笔记</td><td>摘录外部信息，标明来源</td><td>里面应该全是别人的话</td></tr><tr><td>永久笔记</td><td>用自己的话重写，形成可复用的观点</td><td>如果删掉原文还看得懂，才算合格</td></tr><tr><td>原子笔记</td><td>一篇只讲一件事</td><td>标题写不出一个单句，就该拆</td></tr><tr><td>MOC</td><td>把同一主题的多篇聚成一个入口</td><td>攒够三篇再建，早建是负担</td></tr><tr><td>常青笔记</td><td>持续更新，随认知一起长</td><td>三个月没被打开，说明该删</td></tr><tr><td>卡片盒</td><td>用链接把孤立笔记连成网络</td><td>每篇至少连两篇，否则是孤岛</td></tr></tbody></table><p>注意第七个「卡片盒」不是一种笔记，是<strong>前六个的组织方式</strong>。它不出现在某一环，它贯穿全程。</p><h2 id="二、把它跑起来-两个完整走位" tabindex="-1">二、把它跑起来：两个完整走位 <a class="header-anchor" href="#二、把它跑起来-两个完整走位" aria-label="Permalink to “二、把它跑起来：两个完整走位”">​</a></h2><p>光看表格不会用。下面走两遍。</p><h3 id="走位一-读一篇技术长文" tabindex="-1">走位一：读一篇技术长文 <a class="header-anchor" href="#走位一-读一篇技术长文" aria-label="Permalink to “走位一：读一篇技术长文”">​</a></h3><p>假设你在读一篇关于检索增强生成的综述。</p><p><strong>① 捕获（闪念）</strong>——读到一半突然想到「切分粒度太细会丢上下文，太粗会稀释语义」。这个念头十秒内丢进收件箱，不解释、不排版、不等想清楚。闪念笔记的价值在于<strong>速度</strong>，一旦开始整理，念头就凉了。</p><p><strong>① 捕获（文献）</strong>——综述里关于分块策略的几段话值得留。摘录下来，<strong>把原文链接一起存</strong>。文献笔记里应该几乎全是别人的话，加一点点「这段在说啥」的批注就够。混进太多自己的观点，以后就分不清哪句是自己想的。</p><p><strong>② 精炼（永久 + 原子）</strong>——把上面两份原料合起来，<strong>用自己的话</strong>写一篇《分块策略的权衡》。一个笔记只讲一个概念，所以它只谈分块，不谈嵌入、不谈重排。写完链接到另外两篇：一篇讲嵌入向量，一篇讲召回率。</p><p>这一步是全流程唯一真正产生知识的地方。前两步只是搬运，这一步才发生消化。判断标准很硬：<strong>把原文关掉，这篇还看得懂吗？</strong> 看不懂说明你在抄，不是在写。</p><p><strong>③ 存储</strong>——放进它该在的领域目录。归位本身不产生价值，但放错位置的笔记等于不存在，因为以后找不到。</p><p><strong>④ 组织（MOC）</strong>——当分块、嵌入、检索、重排、生成这几篇都攒起来了（三篇以上），建一个《检索增强生成专题》聚合页，把它们串起来。</p><p><strong>别提前建。</strong> 只有一篇的时候建 MOC，是在给自己造一个空文件夹。</p><p><strong>⑤ 演进（常青）</strong>——半年后做项目，发现长文档需要递归分块。回到《分块策略的权衡》，把新案例补进去。</p><p>这篇笔记从「一次写作」变成了「一个持续生长的判断」。这就是常青的意思——不是文笔好，是<strong>它被反复修改过</strong>。</p><p><strong>全程（卡片盒）</strong>——上面每篇笔记里的链接，最终织成一张能走通的网。这张网的作用是：半年后你忘了当初怎么想的，但顺着链接能走回去。</p><h3 id="走位二-读一份团队协作指南" tabindex="-1">走位二：读一份团队协作指南 <a class="header-anchor" href="#走位二-读一份团队协作指南" aria-label="Permalink to “走位二：读一份团队协作指南”">​</a></h3><p>换成非技术内容，流程完全一样，只是落点不同。</p><ul><li><strong>闪念</strong>：「评审应该关注逻辑而不是格式」——一句话，丢进收件箱。</li><li><strong>文献</strong>：Google 的代码评审指南里关于「什么是必须拦下的问题」的那几段，摘录加链接。</li><li><strong>永久 + 原子</strong>：《代码评审的核心原则》，一篇只讲原则，链接到《反馈技巧》和《团队协作》。</li><li><strong>组织</strong>：评审、需求对齐、迭代协作这几篇攒够三篇后，建《团队能力》聚合页。</li><li><strong>常青</strong>：一次激烈的评审争执之后，回来给这篇补上「冲突怎么处理」。</li></ul><h2 id="三、四条不能破的约束" tabindex="-1">三、四条不能破的约束 <a class="header-anchor" href="#三、四条不能破的约束" aria-label="Permalink to “三、四条不能破的约束”">​</a></h2><p>流程可以简化，但下面四条一破，整套就退化成文件夹整理术。</p><p><strong>第一，顺序不能跳。</strong> 闪念 → 文献 → 永久，构成「捕获 → 消化 → 沉淀」的闭环。跳过闪念，你会在读到一半时开始写正式笔记，然后发现写不下去，因为还没读完。跳过永久笔记，你会有一堆摘录，然后以为自己学过。</p><p><strong>第二，领域不能混。</strong> 技术内容、工程实践、思维方法，各有各的位置。混放的直接后果不是乱，是<strong>同主题的东西散在三个地方，谁都不知道另外两处在哪</strong>。</p><p><strong>第三，链接不能省。</strong> 每篇永久笔记至少连两篇相关笔记。这条约束看起来繁琐，但它是唯一能让「卡片盒」真的成立的动作。写链接的时候你会被迫想「这跟什么有关」，而这个思考本身就是价值。</p><p><strong>第四，常青不能懒。</strong> 高频引用的笔记要定期回访。不回访的后果是：你半年前的错误理解，会以权威笔记的形式一直躺在库里，被你自己反复引用。<strong>没被修改过的笔记不是资产，是负债。</strong></p><h2 id="四、最常见的失败方式" tabindex="-1">四、最常见的失败方式 <a class="header-anchor" href="#四、最常见的失败方式" aria-label="Permalink to “四、最常见的失败方式”">​</a></h2><p>不是选错方法，是<strong>在最贵的那一步偷懒</strong>。</p><p>七个工位里，前两个便宜（十秒、几分钟），第四个之后才贵（组织、维护）。所以人的本能是从第三个开始就绕过——摘录完直接扔进文件夹，建个目录假装已经组织了。</p><p>半年后打开库，里面有三百篇文件，但你写不出一篇能直接用的文章。<strong>因为三百篇里，没有一篇是你的话。</strong></p><p>补救的办法不是整理旧笔记，是<strong>从现在开始，每收一份原料，必须当天写出一篇自己的话</strong>。哪怕只有三行。三行的永久笔记，比三十篇摘录有用。</p><hr>',37)),i("p",null,[t[1]||(t[1]=o("这套流水线管的是「怎么流转」。至于「放哪里」是另一套判断，见 ",-1)),e(a,{href:"/nebula-blog/vault/Knowledge/Methods/知识库批量改动前要做的第一件事.html"},{default:h(()=>[...t[0]||(t[0]=[o("知识库批量改动前要做的第一件事",-1)])]),_:1}),t[2]||(t[2]=o("——在动结构之前先留一个能回去的点，否则你整理的不是知识，是风险。",-1))]),e(n),e(s)])}const k=d(_,[["render",b]]);export{N as __pageData,k as default};
